changeSet.sql:
INSERT INTO book (id, name, isbn, available) SELECT md5('lt-book-' || g)::uuid, 'Catalogue Volume ' || lpad(g::text, 6, '0'), '979' || lpad(g::text, 10, '0'), TRUE FROM generate_series(1, 300000) AS g;
INSERT INTO member (id, name, email, password, enabled) SELECT md5('lt-member-' || g)::uuid, 'Registered Reader ' || lpad(g::text, 6, '0'), 'reader.' || g || '@library.example.com', 'password', TRUE FROM generate_series(1, 100000) AS g;
INSERT INTO borrowing (id, book_id, requested_book_id, member_id, borrow_date, return_date, status) SELECT md5('lt-borrowing-' || g)::uuid, md5('n1-book-' || (((g - 1) % 2000) + 1))::uuid, md5('n1-book-' || (((g - 1) % 2000) + 1))::uuid, md5('n1-member-' || (((g - 1) % 200) + 1))::uuid, TIMESTAMP '2020-01-01 10:00:00' + g * INTERVAL '1 minute', TIMESTAMP '2020-01-08 10:00:00' + g * INTERVAL '1 minute', 'RETURNED' FROM generate_series(1, 1000000) AS g;
INSERT INTO book_fine_rate (id, book_id, price_per_day_overdue, effective_date) SELECT md5('lt-fine-rate-' || g)::uuid, md5('lt-book-' || (((g - 1) % 300000) + 1))::uuid, 0.50 + (g % 10) * 0.25, DATE '2020-01-01' + (g % 1500) FROM generate_series(1, 500000) AS g;
ANALYZE book; ANALYZE member; ANALYZE borrowing; ANALYZE book_fine_rate;
